// SPDX-License-Identifier: MIT
pragma solidity >=0.4.22 <0.9.0;

contract IdentityContract {
    constructor() {
        createIdentity(
            "Daniel",
            "Smith",
            "1234 Main St, New York, NY 10030",
            "2000-07-04",
            "SATJ000704HDGLRVA4",
            payable(0x083C1ae5Dd668EcEc2eEee69152Ee5E8BDE1CcA6)
        );
    }

    // Identity
    uint public identityCount = 0;

    event IdentityCreated(
        uint id,
        string firstName,
        string lastName,
        string addresss,
        string birthDate,
        string personalId,
        bytes32 uniqueId,
        uint createdAt
    );

    event IdentityUpdated(
        uint id,
        string firstName,
        string lastName,
        string addresss,
        string birthDate,
        string personalId
    );

    event IdentityDeleted(uint id);

    struct Identity {
        uint id;
        string firstName;
        string lastName;
        string addresss;
        string birthDate;
        string personalId;
        address account;
        bytes32 uniqueId;
        uint createdAt;
    }

    mapping(uint => Identity) public identities;

    function uniqueIdentifier(
        string memory data
    ) public pure returns (bytes32) {
        bytes32 hash = keccak256(bytes(data));
        return hash;
    }

    function createIdentity(
        string memory _firstName,
        string memory _lastName,
        string memory _addresss,
        string memory _birthDate,
        string memory _personalId,
        address payable recipient
    ) public payable {
        identityCount++;
        bytes32 uniqueId = uniqueIdentifier(_personalId);

        identities[identityCount] = Identity(
            identityCount,
            _firstName,
            _lastName,
            _addresss,
            _birthDate,
            _personalId,
            0x083C1ae5Dd668EcEc2eEee69152Ee5E8BDE1CcA6,
            uniqueId,
            block.timestamp
        );
        emit IdentityCreated(
            identityCount,
            _firstName,
            _lastName,
            _addresss,
            _birthDate,
            _personalId,
            uniqueId,
            block.timestamp
        );

        recipient.transfer(msg.value);
    }

    // function updateIdentity(
    //     uint _id,
    //     string memory _firstName,
    //     string memory _lastName,
    //     string memory _addresss,
    //     string memory _birthDate,
    //     string memory _personalId
    // ) public {
    //     Identity storage _identity = identities[_id];
    //     _identity.firstName = _firstName;
    //     _identity.lastName = _lastName;
    //     _identity.addresss = _addresss;
    //     _identity.birthDate = _birthDate;
    //     _identity.personalId = _personalId;

    //     identities[_id] = _identity;

    //     emit IdentityUpdated(
    //         _id,
    //         _firstName,
    //         _lastName,
    //         _addresss,
    //         _birthDate,
    //         _personalId
    //     );
    // }

    // function deleteIdentity(uint _id) public {
    //     delete identities[_id];
    //     identityCount--;
    // }

    function searchIdentity(
        string memory _data
    ) public view returns (Identity memory) {
        for (uint i = 1; i <= identityCount; i++) {
            if (
                keccak256(bytes(identities[i].personalId)) ==
                keccak256(bytes(_data))
            ) {
                return identities[i];
            }
        }
        return identities[0];
    }

    function balanceOf(address account) public view returns (uint) {
        return address(account).balance;
    }
}
